// webpack - bundler module graph demo
var modules = { app: ["utils", "router"], utils: [], router: ["utils"] };
var order = [], seen = {};
(function visit(m) { if (seen[m]) return; seen[m] = 1; modules[m].forEach(visit); order.push(m); })("app");
console.log("Bundler: webpack | Targets: web/node/workers");
console.log("Bundle order: " + order.join(" -> "));
console.log("Chunks: app.[hash].js (entry), shared utils deduplicated -> PASS");

